program
	.command("deploy-fortigate-vm")
	.summary("deploy-fortigate-vm --node <node> [--vmid <vmid:number>] [--name <name>] [--image <image>] [--image-url <image-url>] [--raw <json>]")
	.description("Deploy a FortiGate-VM from Fortinet's KVM qcow2 image: import the disk, create the VM with a WAN NIC (port1) and optional LAN/extra NICs (port2, port3...) on chosen bridges and VLANs, wait for the import, and optionally start it. Give either image (an import-content volume such as local:import/fortios.qcow2) or image_url (a URL of the .qcow2 itself; Fortinet's download is a .zip, so unzip it and serve the qcow2). Defaults (1 vCPU, 2 GB) fit the free permanent evaluation license, which allows at most 3 interfaces. Returns each FortiGate port with its MAC so you can reserve DHCP leases.")
	.usage("--node <node> [--vmid <vmid:number>] [--name <name>] [--image <image>] [--image-url <image-url>] [--raw <json>]")
	.option('--raw <json>', 'Provide raw JSON arguments to the tool, bypassing flag parsing.')

